#include <stdlib.h>
#include <string.h>

// Define the structure for ExprDef
typedef struct {
    int *keysyms;
    size_t keysyms_len;
    size_t keysyms_cap;
    // Additional fields can be added here as needed
} ExprDef;

ExprDef* append_keysym_list(ExprDef *expr, ExprDef *append) {
    // Validate inputs
    if (!expr || !append) {
        return expr; // Return original expr if append is null
    }

    // Calculate the new capacity needed
    size_t new_cap = expr->keysyms_cap + append->keysyms_len;

    // If current capacity is insufficient, reallocate
    if (new_cap > expr->keysyms_cap) {
        int *new_keysyms = realloc(expr->keysyms, new_cap * sizeof(int));
        if (!new_keysyms) {
            return expr; // Return original expr if realloc fails
        }
        expr->keysyms = new_keysyms;
        expr->keysyms_cap = new_cap;
    }

    // Copy the keysyms from append to expr
    size_t copy_len = append->keysyms_len;
    memcpy(expr->keysyms + expr->keysyms_len, append->keysyms, copy_len * sizeof(int));
    expr->keysyms_len += copy_len;

    // Free the memory associated with append
    free(append->keysyms);
    free(append);

    return expr;
}
